$_MODULE['<{sudemi}prestashop>sudemi_1bd983391f0e9675405614baf1ed990c'] = 'sudemi bu siteden gelen istekleri reddetti: bu mağaza sudemi\'ye farklı bir adresle bağlı (%s). Bu site bir test (staging) kopyası veya geri yüklenmiş bir yedekse, sudemi bağlantısını burada kesin. Mağaza bu adrese taşındıysa yeniden bağlayın.';
$_MODULE['<{sudemi}prestashop>sudemi_ce1ed32e41d97b80d80b33148f53f789'] = 'sudemi bu siteden gelen istekleri reddetti: bu mağaza sudemi\'ye farklı bir adresle bağlı. Bu site bir test (staging) kopyası veya geri yüklenmiş bir yedekse, sudemi bağlantısını burada kesin. Mağaza bu adrese taşındıysa yeniden bağlayın.';
$_MODULE['<{sudemi}prestashop>sudemi_432e26275e5095d41313deeb350c7ea2'] = 'Önce bu mağazayı sudemi\'ye bağlayın.';
$_MODULE['<{sudemi}prestashop>sudemi_a473565a143cf3cdb01895753a94ccab'] = 'İade kabul edildi. Alıcıya ürünü geri göndermesi söylenir. Ürün geri geldiğinde bu siparişi her zamanki gibi iade edin (Geri ödendi durumu veya bir kısmı için iade faturası): iade sudemi üzerinden alıcıya gider ve talebi kapatır.';
$_MODULE['<{sudemi}prestashop>sudemi_cb2539cea371b3e5736c3444acbfccf9'] = 'İade reddedildi. sudemi gerekçenizi alıcıya gösterir.';
$_MODULE['<{sudemi}prestashop>sudemi_8af7448f2470dbdf3e3c52b23b771e9d'] = 'Bu iade talebi zaten yanıtlanmıştı (sudemi\'de veya süre dolduktan sonra sudemi tarafından). Hiçbir şey değiştirilmedi.';
$_MODULE['<{sudemi}prestashop>sudemi_9fba5e140e3eeeef1fb479338a5f0a00'] = 'sudemi\'de bu sipariş için açık bir iade talebi yok. Listeden kaldırıldı.';
$_MODULE['<{sudemi}prestashop>sudemi_77045abe2681e10ec8585af1568a531d'] = 'Bir iadeyi reddetmek için bir gerekçe yazın. Gerekçe alıcıya gösterilir.';
$_MODULE['<{sudemi}prestashop>sudemi_f56cb5d64a1b05252377f64a8a6995b3'] = 'sudemi bu yanıtı kabul etmedi. Ret için bir gerekçe gerekir; kontrol edip yeniden deneyin.';
$_MODULE['<{sudemi}prestashop>sudemi_98cb3df4ed609dceaddc55efce570395'] = 'İade talepleri';
$_MODULE['<{sudemi}prestashop>sudemi_0eba7b42b6c53cdc949279b9d1e6ac3c'] = 'Alıcılar teslim edilen bu siparişleri iade etmek istiyor. Her birini yanıt tarihinden önce yanıtlayın: kabul edin veya bir gerekçeyle reddedin (gerekçe alıcıya gösterilir). Yanıt verilmezse sudemi karar verir. Kabul ettikten sonra ürün geri geldiğinde siparişi iade edin.';
