$_MODULE['<{sudemi}prestashop>sudemi_1d75c6794f7c6f15f9d20716a7534e15'] = 'sudemi %1$s ile ödeme kabul etmez, bu yüzden ürünleriniz alıcılara gösterilmez. sudemi şu para birimlerini kabul eder: %2$s. Bunlardan birini bu mağazanın varsayılan para birimi olarak seçin, ardından kataloğu yeniden gönderin.';
